        {
          "@type": "HowToStep",
          "position": 1,
          "name": "Request a Quote",
          "text": "Contact STS by phone or online form and provide equipment types, quantities, site access details, and preferred timing for your Bakersfield pickup.",
          "url": "https://www.stselectronicrecyclinginc.com/CONTACT-STS-PAGE"
        },
        {
          "@type": "HowToStep",
          "position": 2,
          "name": "Review Equipment Scope",
          "text": "Review the computers, servers, networking hardware, displays, mobile devices, printers, and other retired electronics included in the collection plan."
        },
        {
          "@type": "HowToStep",
          "position": 3,
          "name": "Schedule Collection",
          "text": "Coordinate a pickup window that supports normal business operations, loading access, equipment volume, and secure staging requirements."
        },
        {
          "@type": "HowToStep",
          "position": 4,
          "name": "Document Asset Handling",
          "text": "Equipment is collected with chain of custody documentation to support clear records for retired assets and applicable data-bearing devices."
        },
        {
          "@type": "HowToStep",
          "position": 5,
          "name": "Process Equipment",
          "text": "Assets are evaluated for appropriate data handling, reuse opportunities, component recovery, and responsible electronic material recycling."
        },
        {
          "@type": "HowToStep",
          "position": 6,
          "name": "Receive Documentation",
          "text": "Receive applicable chain of custody records and Certificates of Destruction to support asset disposition files, reporting, and audit preparation.",
          "url": "https://www.stselectronicrecyclinginc.com/certificate-of-destruction-services"
        }
      ]
